/* eslint-disable no-undef */
/* eslint-disable no-console */
import React, { useState, useEffect } from "react";

export default function SafetyCheck() {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");
  const [loading, setLoading] = useState(false);

  // 🔹 Auto-detect user location on page load
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLatitude(position.coords.latitude);
          setLongitude(position.coords.longitude);
          console.log("Location fetched:", position.coords);
        },
        (error) => {
          console.error("Error fetching location:", error);
          setResult("Please allow location access in your browser.");
        }
      );
    } else {
      setResult("Geolocation is not supported by your browser.");
    }
  }, []);

  // 🔹 Check Safety Function
  const handleCheckSafety = async () => {
    try {
      setLoading(true);
      const response = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          latitude: parseFloat(latitude),
          longitude: parseFloat(longitude),
        }),
      });

      if (!response.ok) throw new Error("Network response was not ok");

      const data = await response.json();
      setResult(data.message);
    } catch (error) {
      console.error("Error checking safety:", error);
      setResult("Error checking safety");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ textAlign: "center", marginTop: "50px" }}>
      <h2>Smart Tourist Safety Check</h2>

      <p>
        <strong>Latitude:</strong> {latitude ? latitude : "Fetching..."}
        <br />
        <strong>Longitude:</strong> {longitude ? longitude : "Fetching..."}
      </p>

      <button
        onClick={handleCheckSafety}
        disabled={!latitude || !longitude || loading}
      >
        {loading ? "Checking..." : "Check Safety"}
      </button>

      {result && (
        <p style={{ marginTop: "20px", fontWeight: "bold" }}>{result}</p>
      )}
    </div>
  );
}
